import {parseCatalog,recommend,CATEGORIES,FORMATS,REASONS,money} from './engine.mjs';
const $=s=>document.querySelector(s), form=$('#request');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalog=[], original=[], last=null;
const defaults={city:'Алматы',date:'2026-11-14',event_format:'корпоратив',category:'Ведущий',budget:1200000,hours:4,language:'русский',wishes:'интеллигентный атмосферный'};
export const demos={autumn:{...defaults},next:{...defaults,date:'2026-11-15'},rare:{...defaults,category:'Флорист',budget:250000,wishes:'цветочные'},empty:{...defaults,budget:50000},absent:{...defaults,category:'Отель'},venue:{...defaults,category:'Банкетный зал',wishes:'панорамный свет'}};
function options(id, values, empty=false) {
 const e=$('#'+id), prev=e.value; e.replaceChildren();
 if(empty)e.add(new Option('Любой',''));
 for(const s of [...new Set(values)])e.add(new Option(s,s));
 if([...e.options].some(o=>o.value===prev))e.value=prev;
}
function setFields(q){for(const [k,v] of Object.entries(q))if(form.elements[k]){const e=form.elements[k];if(e.tagName==='SELECT' && ![...e.options].some(o=>o.value===String(v)))e.add(new Option(v,v));e.value=v??''}}
function prepare(){options('city',['Алматы','Астана','Зарубежье',...catalog.map(p=>p.city)]);options('category',[...CATEGORIES,...catalog.flatMap(p=>p.categories)]);options('event_format',[...FORMATS,...catalog.flatMap(p=>p.event_formats)]);options('language',['русский','казахский','английский',...catalog.flatMap(p=>p.languages)],true);$('#catalog-status').textContent=`В каталоге ${catalog.length} профилей · синтетических ${catalog.filter(p=>p.synthetic).length}`;}
function render(r,ms){
 const titles={matched:'Ваш короткий список',category_absent:'В городе нет этой категории',no_matches:'Никто не проходит все условия'};
 let html=`<div class="result-heading"><h2>${titles[r.status]}</h2><span class="timing">${ms.toFixed(1)} мс · подбор</span></div><p class="result-summary">${esc(r.message)}</p>`;
 if(!r.cards.length)html+=`<div class="empty"><div class="state-label">${r.status==='category_absent'?'КАТЕГОРИЯ ОТСУТСТВУЕТ':'КАНДИДАТЫ ЕСТЬ, СОВПАДЕНИЙ НЕТ'}</div><h2>${r.status==='category_absent'?'Попробуйте другую категорию или город':'Измените одно из ограничений'}</h2><p>${r.status==='category_absent'?'Это относится к загруженному каталогу, а не ко всем подрядчикам города.':'Мы не включаем занятых подрядчиков и не ослабляем ваши условия автоматически.'}</p>${r.suggestions.map(s=>`<p>${esc(s)}</p>`).join('')}</div>`;
 html+=r.cards.map((c,i)=>`<article class="card"><div class="card-top"><span class="rank">0${i+1}</span><div class="identity"><h3>${esc(c.name)}</h3><div class="meta">${esc(c.category)} · ${esc(c.city)}</div></div><div class="price">${money(c.price_from_kzt)}<small>от, за мероприятие</small></div></div><div class="badges"><span class="badge ${c.synthetic?'demo':'source'}">${c.added_for_demo?'Добавленный демопрофиль':c.synthetic?'Синтетический профиль датасета':'Исходный анонимизированный профиль'}</span><span class="badge">Свободен по календарю · ${esc(r.query.date)}</span>${c.price_imputed?'<span class="badge demo">Цена проставлена при подготовке</span>':''}${c.city_imputed?'<span class="badge demo">Город проставлен при подготовке</span>':''}</div><div class="why"><div class="why-label">ПОЧЕМУ ПОДХОДИТ</div><p class="explanation">${esc(c.explanation)}</p></div>${r.query.wishes?`<p class="match-words">${c.evidence.matches.length?`Совпадения с пожеланиями: ${c.evidence.matches.map(esc).join(', ')}.`:'Совпадений слов с пожеланиями нет; подходит по обязательным условиям.'}</p>`:''}<details class="card-details"><summary>Детали и оценка</summary><p>ID: ${esc(c.id)} · Языки: ${c.languages.map(esc).join(', ')} · ${c.max_hours===null?'Не привязан к часам присутствия':`До ${c.max_hours} ч на площадке`}<br>Баллы за описание: ${c.score_breakdown.description}; за запас бюджета: ${c.score_breakdown.budget}; всего: ${c.score}. Это оценка соответствия запросу, а не качества подрядчика.</p></details></article>`).join('');
 if(r.rejected_profiles.length)html+=`<details class="audit"><summary>Почему не попали остальные (${r.rejected_profiles.length})</summary><p>Один профиль может не пройти несколько условий. Поэтому суммы причин могут превышать число исключённых.</p><ul>${r.rejected_profiles.map(p=>`<li><strong>${esc(p.name)}</strong>: ${p.reasons.map(x=>esc(REASONS[x])).join('; ')}.</li>`).join('')}</ul></details>`;
 $('#results').innerHTML=html;last=r;delete document.body.dataset.stale;
}
function run(q=Object.fromEntries(new FormData(form))){const start=performance.now();const r=recommend(catalog,q);setFields(r.query);render(r,performance.now()-start);return r}
function showError(e){$('#results').innerHTML=`<div class="empty" role="alert"><h2>Проверьте параметры</h2><p class="error">${esc(e.message)}</p></div>`;last=null;delete document.body.dataset.stale}
form.addEventListener('submit',e=>{e.preventDefault();try{run()}catch(e){showError(e)}});
form.addEventListener('input',()=>{document.body.dataset.stale='true';document.querySelectorAll('[data-demo]').forEach(b=>b.classList.remove('active'))});
for(const b of document.querySelectorAll('[data-demo]'))b.addEventListener('click',()=>{try{run(demos[b.dataset.demo]);document.querySelectorAll('[data-demo]').forEach(el=>el.classList.toggle('active',el===b))}catch(e){showError(e)}});
$('#upload').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10*1024*1024)throw new Error('Максимальный размер файла — 10 МБ.');const next=parseCatalog(await f.text(),f.name);catalog=next;prepare();run();$('#upload-status').className='';$('#upload-status').textContent=`Загружено ${catalog.length} профилей из ${f.name}.`;}catch(e){$('#upload-status').className='error';$('#upload-status').textContent=e.message}finally{e.target.value=''}});
$('#reset-data').addEventListener('click',()=>{catalog=original;prepare();run(defaults);$('#upload-status').textContent='Демокаталог восстановлен.';$('#upload-status').className=''});
try{const response=await fetch('/catalog.jsonl');if(!response.ok)throw new Error('Не удалось загрузить каталог. Обновите страницу.');catalog=parseCatalog(await response.text());original=catalog;prepare();run(defaults);document.querySelector('[data-demo="autumn"]').classList.add('active')}catch(e){showError(e);$('#submit').disabled=true;$('#catalog-status').textContent='Каталог недоступен'}
if(document.modelContext?.registerTool){try{await document.modelContext.registerTool({name:'recommend_contractors',title:'Подобрать подрядчиков',description:'Подобрать до трёх подрядчиков из текущего каталога и показать результат на странице.',inputSchema:{type:'object',properties:{city:{type:'string'},date:{type:'string'},event_format:{type:'string'},category:{type:'string'},budget:{type:'integer',minimum:1},hours:{type:'number',exclusiveMinimum:0,maximum:72},language:{type:'string'},wishes:{type:'string',maxLength:500}},required:['city','date','event_format','category','budget'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){const result=run(input);return {status:result.status,cards:result.cards,message:result.message}}})}catch(e){console.warn('WebMCP недоступен',e.message)}}
